export const assignmentVisual = "<!doctype html>\n<html lang=\"en\">\n  <meta charset=\"utf-8\" />\n  <style>\n    html,\n    body {\n      margin: 0;\n      background: #000;\n      color: #fff;\n      width: 100%;\n      height: 100%;\n    }\n    svg {\n      width: 100%;\n      height: 100%;\n      display: block;\n    }\n    text {\n      fill: #fff;\n      font-family: Georgia, serif;\n      font-size: 22px;\n    }\n  </style>\n  <svg\n    viewBox=\"0 0 540 820\"\n    xmlns=\"http://www.w3.org/2000/svg\"\n    aria-label=\"Balanced assignment of matrix blocks to two GPUs\"\n  >\n    <text x=\"30\" y=\"35\">Matrix pool · sizes in MB</text>\n    <text x=\"270\" y=\"395\" text-anchor=\"middle\">Balanced assignment</text>\n    <text x=\"30\" y=\"600\">GPU 1</text>\n    <text x=\"290\" y=\"600\">GPU 2</text>\n    <text id=\"load-0\" x=\"50\" y=\"785\"></text>\n    <text id=\"load-1\" x=\"310\" y=\"785\"></text>\n    <g fill=\"none\" stroke=\"#fff\" stroke-width=\"1.5\">\n      <rect x=\"30\" y=\"50\" width=\"480\" height=\"300\" />\n      <rect x=\"30\" y=\"415\" width=\"480\" height=\"125\" />\n      <path d=\"M270 350V365 M270 405V415 M270 540V570 M140 610V570H400V610\" />\n      <rect x=\"30\" y=\"615\" width=\"220\" height=\"180\" />\n      <rect x=\"290\" y=\"615\" width=\"220\" height=\"180\" />\n    </g>\n    <g id=\"blocks\"></g>\n  </svg>\n  <script>\n    const colors = [\"#65b9ff\", \"#ffbd69\", \"#65d6a2\", \"#d69cff\"];\n    const sizes = [6, 5, 2, 1];\n    const loads = [0, 0];\n    // Largest first, then place each matrix on the less loaded GPU.\n    const assignments = sizes.map((size) => {\n      const gpu = loads[0] <= loads[1] ? 0 : 1;\n      loads[gpu] += size;\n      return gpu;\n    });\n    const group = document.getElementById(\"blocks\");\n    const blocks = colors.map((color, i) => {\n      const g = document.createElementNS(\"http://www.w3.org/2000/svg\", \"g\");\n      g.innerHTML = `<rect width=\"${48 + sizes[i] * 22}\" height=\"44\" fill=\"${color}\" fill-opacity=\".25\" stroke=\"${color}\" stroke-width=\"1.5\"/><text x=\"8\" y=\"30\">W${String.fromCharCode(0x2081 + i)} · ${sizes[i]}</text>`;\n      group.append(g);\n      return g;\n    });\n    window.lbgosVisual = {\n      steps: [\n        { label: \"Four matrices have sizes 6, 5, 2 and 1 MB.\" },\n        { label: \"Assign W₁ and W₂ to different GPUs.\", duration: 1800 },\n        { label: \"Place each smaller matrix on the less loaded GPU: 7 MB each.\", duration: 1800 },\n      ],\n      captions: [\n        \"Watch the four matrices waiting in the pool. Their sizes add up to $14$ MB, so an even split would put $7$ MB on each GPU.\",\n        \"Watch the two largest matrices move to different GPUs. The smaller matrices can now fill the difference between their loads.\",\n        \"Each smaller matrix goes to the GPU with less work. Both GPUs finish with $7$ MB, so neither waits for a heavier assignment.\",\n      ],\n      render(step, t) {\n        const assignedLoads = [0, 0];\n        blocks.forEach((block, i) => {\n          const phase = i < 2 ? 1 : 2;\n          const progress = step < phase ? 0 : step > phase ? 1 : t;\n          const gpu = assignments[i];\n          const start = [50 + gpu * 260, 255 - Math.floor(i / 2) * 140];\n          const end = [start[0], 720 - Math.floor(i / 2) * 70];\n          if (progress === 1) assignedLoads[gpu] += sizes[i];\n          // Fill from the bottom so moving blocks never cross a waiting or assigned block.\n          const middle = [start[0], 455];\n          const a = progress < 0.5 ? start : middle;\n          const b = progress < 0.5 ? middle : end;\n          const u = progress < 0.5 ? progress * 2 : progress * 2 - 1;\n          block.setAttribute(\n            \"transform\",\n            `translate(${a[0] + (b[0] - a[0]) * u},${a[1] + (b[1] - a[1]) * u})`,\n          );\n        });\n        assignedLoads.forEach((load, gpu) => {\n          document.getElementById(`load-${gpu}`).textContent = `Load: ${load} MB`;\n        });\n      },\n    };\n  </script>\n</html>\n";
